import { PickD3Scale } from '@visx/scale';

import { ChartUnit } from '../../../types/chart-unit.js';
import { Formatter } from '../../../types/formatter.js';
import { MouseCoordinate } from '../../../types/overlays.js';

export function getMagnifierLabel(
  unit: ChartUnit,
  coordinate: 'y' | 'x',
  formatter: Formatter,
  mousePosition?: MouseCoordinate,
  valueScale?: PickD3Scale<'linear'>,
) {
  if (!mousePosition || !valueScale) {
    return;
  }

  let value = valueScale.invert(mousePosition[coordinate]);

  if (unit === 'duration') {
    value = Math.round(value);
  }

  return formatter(value, unit);
}
